/**
 * Four sample cases for the design review page and the welcome mini-trail, taken from the real demo world.
 * Patients and messages come straight from data/*.json. Each result is real pipeline output (lib/pipeline run on the
 * message), generated by lib/fixtures/build-samples.ts into sample-results.json; only the sorter's verdict and the
 * draft wording are scripted. Regenerate with:
 *   npx tsx lib/fixtures/build-samples.ts > lib/fixtures/sample-results.json
 *
 *   routine   MSG-0152, Priya (AU) asks if her order has shipped: checked draft, route "draft"
 *   blocked   MSG-0023, Aroha (NZ) asks why her price went up: the draft states a notice period the policy does not,
 *             so the fact check blocks it, route "person"
 *   clinical  MSG-0127, Priya (AU) asks about taking her capsules with new tablets: stopped by the safety rules before
 *             any AI, route "clinician"
 *   urgent    MSG-0143, a family member reports Anjali's (NZ) death and asks to stop orders: stopped, orders on hold,
 *             route "urgent"
 *
 * Every person, order and message is fictional.
 */
import patientsData from "@/data/patients.json";
import messagesData from "@/data/messages.json";
import samples from "./sample-results.json";
import type { Patient, PatientMessage, PipelineResult } from "@/lib/types";

export interface SampleCase {
  key: "routine" | "blocked" | "clinical" | "urgent";
  label: string;
  patient: Patient;
  message: PatientMessage;
  result: PipelineResult;
  /** The exact text the safety rules ran on (subject, then body). Pass it to <Trail messageText>. */
  text: string;
}

/** Same as messageText() in lib/pipeline/run.ts, inlined so this module does not pull the pipeline into a page bundle. */
function messageText(m: PatientMessage): string {
  return m.subject ? `${m.subject}\n\n${m.body}` : m.body;
}

const patients = patientsData as unknown as Patient[];
const messages = messagesData as unknown as PatientMessage[];

interface RawCase {
  key: SampleCase["key"];
  label: string;
  patientId: string;
  messageId: string;
  result: unknown;
}

export const SAMPLE_CASES: SampleCase[] = (samples.cases as RawCase[]).map((c) => {
  const patient = patients.find((p) => p.id === c.patientId);
  const message = messages.find((m) => m.id === c.messageId);
  if (!patient || !message) throw new Error(`Sample case ${c.key}: ${c.patientId} or ${c.messageId} is missing from data/`);
  return {
    key: c.key,
    label: c.label,
    patient,
    message,
    result: c.result as PipelineResult,
    text: messageText(message),
  };
});

export const SAMPLE_PATIENTS: Patient[] = SAMPLE_CASES.map((c) => c.patient);
export const SAMPLE_MESSAGES: PatientMessage[] = SAMPLE_CASES.map((c) => c.message);
export const SAMPLE_RESULTS: PipelineResult[] = SAMPLE_CASES.map((c) => c.result);

export function sampleCase(key: SampleCase["key"]): SampleCase {
  const c = SAMPLE_CASES.find((x) => x.key === key);
  if (!c) throw new Error(`Unknown sample case: ${key}`);
  return c;
}
